import React, { useState } from 'react';
import './PackerPage.css';

const PackerPage = () => {
  const cityData = {
    "Yamunanagar": "https://d3sftlgbtusmnv.cloudfront.net/blog/wp-content/uploads/2024/10/Chaneti-Stupa.jpg",
    "Kurukshetra": "https://thumbs.dreamstime.com/b/sarveshwar-mahadev-temple-brahma-sarovar-kurukshetra-sarveshwar-mahadev-temple-located-brahma-sarovar-kurukshetra-india-428706026.jpg",
    "Chandigarh": "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/09/4c/43/64/the-rock-garden-of-chandigarh.jpg?w=900&h=500&s=1",
    "Karnal": "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/04/7a/f4/f0/noor-mahal.jpg?w=1400&h=1400&s=1",
  };

  const [selectedCity, setSelectedCity] = useState("Yamunanagar");

  // 1. FIX: Define the routes variable that was causing the error
  const routes = [
    { to: 'Delhi', kms: '200km', price: '4500' },
    { to: 'Chandigarh', kms: '105km', price: '2500' },
    { to: 'Gurgaon', kms: '240km', price: '5200' },
  ];

  // 2. NEW: Extra Services (Icons from your screenshot)
  const extraServices = [
    { name: 'Rope pulling services', desc: 'Assistance in handling heavy goods', icon: '🪝' },
    { name: 'Installation of Appliances', desc: 'Un-installation and installation', icon: '⚙️' },
    { name: 'Professional Electrician', desc: 'Expertise at your rescue', icon: '⚡' },
    { name: 'Professional Carpenter', desc: 'Skilled furniture handling', icon: '🪚' },
  ];

  // 3. NEW: Testimonials
  const reviews = [
    { name: 'Vikas', city: 'Bangalore', text: 'Porters team was punctual and highly professional.' },
    { name: 'Praveen', city: 'Pune', text: 'Grateful for the punctuality and enthusiasm of the team.' },
  ];

  return (
    <div className="booking-wrapper">
      {/* Hero Section */}
      <section 
        className="hero-section" 
        style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)), url(${cityData[selectedCity]})` }}
      >
        <div className="city-selector-top">
           <select value={selectedCity} onChange={(e) => setSelectedCity(e.target.value)}>
            {Object.keys(cityData).map(city => <option key={city} value={city}>{city}</option>)}
          </select>
        </div>

        <div className="hero-text-center">
            <h1>Packer and Movers in <span className="highlight">{selectedCity}</span></h1>
            <p>100% damage-free shifting with expert handling.</p>
        </div>

        <div className="booking-bar-white">
          <div className="form-input"><label>Pickup Point</label><input type="text" placeholder="Building/Street" /></div>
          <div className="form-input"><label>Drop Location</label><input type="text" placeholder="Area/Landmark" /></div>
          <div className="form-input"><label>Shifting Date</label><input type="date" /></div>
          <button className="check-price-btn">Check Price →</button>
        </div>
      </section>

      {/* Need an Extra Hand Section (From your Screenshot) */}
      <section className="extra-services">
        <h2>Need an Extra Hand?</h2>
        <div className="services-grid">
          {extraServices.map((s, i) => (
            <div key={i} className="service-card">
              <span className="service-icon">{s.icon}</span>
              <h4>{s.name}</h4>
              <p>{s.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Popular Routes Section */}
      <section className="popular-routes">
        <h3>Popular Routes from {selectedCity}</h3>
        <div className="routes-grid">
          {routes.map((route, i) => (
            <div key={i} className="route-card">
              <strong>to {route.to}</strong>
              <span>{route.kms} • Est. ₹{route.price}</span>
            </div>
          ))}
        </div>
      </section>

      {/* Testimonials Section */}
      <section className="testimonials">
        <h3>Some words from our happy customers!</h3>
        <div className="reviews-flex">
          {reviews.map((r, i) => (
            <div key={i} className="review-card">
              <p>"{r.text}"</p>
              <h5>- {r.name}, {r.city}</h5>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default PackerPage;
